import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import page404 from 'assets/images/page-404.webp';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, Page } from 'shared/ui';

import styles from './NotFound.module.scss';

interface INotFoundProps extends HTMLAttributes<HTMLDivElement> {}

export const NotFound: FC<INotFoundProps> = ({ className, ...props }) => {
	const { t } = useTranslation();

	return (
		<Page {...props} className={cn(className, styles.notFound)}>
			<img className={styles.notFound__img} src={page404} alt={t('Страница не найдена')} width="440" height="340" />
			<Typography.Title level={1} className={styles.notFound__title}>
				{t('Страница не найдена')}
			</Typography.Title>
			<Typography.Paragraph className={styles.notFound__text}>
				{t('Возможно, вы допустили опечатку, а может быть, этой страницы никогда не существовало')}
			</Typography.Paragraph>
			<ButtonStyleLink className={styles.notFound__link} to={EMainRoutes.DASHBOARD} size={'large'}>
				{t('Перейти на главную')}
			</ButtonStyleLink>
		</Page>
	);
};

export default NotFound;
